Node (Express) — minimal example using the Stripe Node SDK and express.raw to keep the request body unparsed (required for signature verification):

JavaScript (CommonJS)
```
const express = require('express');
const Stripe = require('stripe');
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

const app = express();

/* Must use raw body for webhook route */
app.post('/webhook', express.raw({ type: 'application/json' }), (req, res) => {
  const sig = req.headers['stripe-signature'];
  const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET;

  let event;
  try {
    // req.body is a Buffer because of express.raw
    event = stripe.webhooks.constructEvent(req.body, sig, endpointSecret);
  } catch (err) {
    console.error('⚠️  Webhook signature verification failed.', err.message);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the event
  switch (event.type) {
    case 'payment_intent.succeeded':
      // const pi = event.data.object;
      break;
    // ... handle other event types
    default:
      console.log(`Unhandled event type ${event.type}`);
  }

  res.json({ received: true });
});

app.listen(4242);
```

Notes:
- Do NOT parse the webhook route body with express.json() — use express.raw({ type: 'application/json' }) so constructEvent can verify the signature.
- Keep your endpoint secret (STRIPE_WEBHOOK_SECRET) private.

