```js
// server.js
const express = require('express');
const Stripe = require('stripe');
const stripe = Stripe(process.env.STRIPE_SECRET_KEY);
const app = express();
app.use(express.json());

app.post('/create-setup-intent', async (req, res) => {
  // supply or create a customerId so the saved card is attached to the customer
  const customerId = req.body.customerId; // required to attach PM to customer
  const setupIntent = await stripe.setupIntents.create({
    customer: customerId,
    payment_method_types: ['card'],
    usage: 'off_session' // indicates future off-session use
  });
  res.json({ clientSecret: setupIntent.client_secret });
});

app.listen(4242);
```

Client (Stripe.js + Elements) — collect card and confirm the SetupIntent
