<!-- index.html -->
<script src="https://js.stripe.com/v3/"></script>
<form id="setup-form">
  <div id="card-element"></div>
  <button type="submit">Save card</button>
</form>

<script>
const stripe = Stripe('pk_test_...'); // your publishable key
const elements = stripe.elements();
const card = elements.create('card');
card.mount('#card-element');

async function fetchClientSecret(customerId){
  const r = await fetch('/create-setup-intent', {
    method: 'POST',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ customerId })
  });
  const j = await r.json();
  return j.clientSecret;
}

document.getElementById('setup-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const customerId = 'cus_...'; // pass the customer id for which you're saving the card
  const clientSecret = await fetchClientSecret(customerId);

  const { setupIntent, error } = await stripe.confirmCardSetup(clientSecret, {
    payment_method: {
      card,
      billing_details: { name: 'Jenny Rosen' }
    }
  });

  if (error) {
    console.error(error.message);
    // show error to user
  } else {
    console.log('SetupIntent successful:', setupIntent);
    // payment_method is saved and attached to the customer (if you created with customer)
    // setupIntent.payment_method contains the PaymentMethod id (pm_...)
  }
});
</script>
```

How to charge later (server)
