```ts
import { EventEmitter } from 'events';
const jobs = new Map<string, EventEmitter>();

export function createJob(id: string) {
  const e = new EventEmitter();
  jobs.set(id, e);
  return e;
}
export function getJob(id: string) {
  return jobs.get(id);
}
export function removeJob(id: string) {
  jobs.delete(id);
}
```

app/actions.ts
