  const e = createJob(id);

  // fire-and-forget async work that emits progress
  (async () => {
    for (let i = 1; i <= 100; i++) {
      await new Promise((r) => setTimeout(r, 50)); // simulate work
      e.emit("progress", i); // emit percent
    }
    e.emit("done");
