app/api/progress/[id]/route.ts
```ts
import { NextResponse } from "next/server";
import { getJob, removeJob } from "@/app/_lib/jobs";

export async function GET(req: Request, { params }: { params: { id: string } }) {
  const id = params.id;
  const job = getJob(id);
  if (!job) return new Response("Not found", { status: 404 });

  const encoder = new TextEncoder();

  const stream = new ReadableStream({
    start(controller) {
      const onProgress = (p: number) =>
        controller.enqueue(encoder.encode(`data: ${JSON.stringify({ progress: p })}\n\n`));
      const onDone = () => {
        controller.enqueue(encoder.encode(`event: done\ndata: {}\n\n`));
        controller.close();
        removeJob(id);
      };

      job.on("progress", onProgress);
      job.on("done", onDone);

      // cleanup if client disconnects
      controller.onerror = controller.oncancel = () => {
        job.off("progress", onProgress);
        job.off("done", onDone);
      };
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache",
      Connection: "keep-alive",
    },
  });
}
```

app/page.tsx (client component)
```tsx
"use client";

import { useState, useEffect } from "react";
import { startLongTask } from "./actions"; // server action import

export default function Page() {
  const [jobId, setJobId] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    if (!jobId) return;
    const es = new EventSource(`/api/progress/${jobId}`);
    es.onmessage = (e) => {
      try {
        const data = JSON.parse(e.data);
        if (data?.progress != null) setProgress(data.progress);
      } catch {}
    };
    es.addEventListener("done", () => {
      es.close();
    });
    return () => es.close();
  }, [jobId]);

  return (
    <main>
      <button
        onClick={async () => {
          const id = await startLongTask(); // calls server action that starts work and returns id
          setJobId(id);
          setProgress(0);
        }}
      >
        Start
      </button>

      <div>Progress: {progress}%</div>
      <progress value={progress} max={100} />
    </main>
  );
}
```

Notes:
- This pattern uses a server action to start work and assign a job id, and an SSE endpoint to stream progress to a client component.
- Works on Node runtime (not Edge) because it uses EventEmitter and ReadableStream server-side.

