```ts
// TypeScript — example showing how to expose a resource using @modelcontextprotocol/sdk Server
import { Server } from '@modelcontextprotocol/sdk';

// Create the Server instance
const server = new Server({
  name: 'example-server',
  description: 'Example MCP server exposing a "notes" resource',
});

// Define a resource and its handlers. The exact handler names/shape below are the
// minimal sensible contract used by MCP-style servers: list, get, and call (action).
const notesResource = {
  id: 'notes',                // canonical resource id
  title: 'Notes',
  description: 'Simple notes resource',
  // optional JSON schema for items (useful for UIs / validation)
  schema: {
    type: 'object',
    properties: {
      id: { type: 'string' },
      text: { type: 'string' },
      createdAt: { type: 'string', format: 'date-time' },
    },
    required: ['id', 'text', 'createdAt'],
  },

  // Handlers the Server will call when the MCP controller asks for operations
  handlers: {
    // return a list of items (support paging/filters via params if needed)
    list: async (params = {}) => {
      // Replace with real data access
      return [
        { id: '1', text: 'First note', createdAt: new Date().toISOString() },
        { id: '2', text: 'Second note', createdAt: new Date().toISOString() },
      ];
    },

    // return a single item by id
    get: async ({ id }: { id: string }) => {
      // Replace with real data access
      return { id, text: `Note ${id}`, createdAt: new Date().toISOString() };
    },

    // an example action/call on the resource (e.g., create)
    call: async ({ action, input }: { action: string; input: any }) => {
      if (action === 'create') {
        const created = {
          id: String(Date.now()),
          text: input.text,
          createdAt: new Date().toISOString(),
        };
        // persist created...
        return created;
      }
      throw new Error(`Unknown action ${action}`);
    },
  },
};

// Expose the resource on the Server
server.exposeResource(notesResource);

// Start listening (API may be `start()` or `listen()`, adapt if your SDK uses a different method)
await server.listen?.(0) ?? await server.start?.();

console.log('MCP Server started and "notes" resource exposed');
```

If your SDK has different method names, substitute server.exposeResource -> server.expose or server.registerResource, and server.listen/start accordingly. The key pieces are: construct Server, provide a resource descriptor (id, schema, handlers), and call the Server method to expose/register it.

