Below is a concise, code-first recipe (single Node.js script) that (1) clones a private GitHub repo, (2) chunks files and indexes them into a generic Nia-compatible embedding/vector index via HTTP, and (3) exposes a tiny MCP-compatible HTTP endpoint that Cursor can call to query the Nia index. Replace the placeholder endpoints and keys with your actual Nia and Cursor/MCP config.

Save as index_and_mcp.js and run with NODE 18+.

index_and_mcp.js
```javascript
/**
 * Usage: 
 *   GITHUB_TOKEN=ghp_xxx GITHUB_REPO=owner/repo NIA_API_KEY=nia_xxx NIA_BASE=https://nia.example.com INDEX_NAME=my-index MCP_PORT=3000 node index_and_mcp.js
 *
 * Notes:
 *  - This is a minimal, adaptable example. Replace the Nia endpoints (/v1/embeddings, /v1/indexes/:index/upsert, /v1/indexes/:index/search)
 *    to match your Nia deployment API surface.
 *  - MCP endpoint here is POST /mcp/query { query: string, top_k?: number } -> returns search hits for Cursor to consume.
 */

import { execSync } from "child_process";
import fs from "fs";
import path from "path";
import fetch from "node-fetch";
import express from "express";

const {
  GITHUB_TOKEN,
  GITHUB_REPO,
  NIA_API_KEY,
  NIA_BASE = "https://nia.example.com",
  INDEX_NAME = "github-repo-index",
  MCP_PORT = 3000,
} = process.env;

if (!GITHUB_TOKEN || !GITHUB_REPO || !NIA_API_KEY) {
  console.error("Set GITHUB_TOKEN, GITHUB_REPO, and NIA_API_KEY environment variables.");
  process.exit(1);
}

/* STEP 1: clone private repo */
const CLONE_DIR = `/tmp/repo_${Date.now()}`;
console.log("Cloning repo...");
execSync(`git clone https://${GITHUB_TOKEN}@github.com/${GITHUB_REPO}.git ${CLONE_DIR}`, { stdio: "inherit" });

/* STEP 2: read & chunk files */
const ALLOWED_EXT = new Set([".md", ".mdx", ".txt", ".js", ".ts", ".py", ".java", ".go", ".json", ".yaml", ".yml", ".html"]);
function walk(dir) {
  const out = [];
  for (const name of fs.readdirSync(dir)) {
    const full = path.join(dir, name);
    const st = fs.statSync(full);
    if (st.isDirectory()) {
      out.push(...walk(full));
    } else {
      if (ALLOWED_EXT.has(path.extname(name).toLowerCase())) out.push(full);
    }
  }
  return out;
}
function chunkText(text, chunkSize = 1000, overlap = 200) {
  const chunks = [];
  let i = 0;
  while (i < text.length) {
    const chunk = text.slice(i, i + chunkSize);
    chunks.push(chunk);
    i += chunkSize - overlap;
  }
  return chunks;
}

console.log("Reading files and creating document chunks...");
const files = walk(CLONE_DIR);
const documents = [];
for (const f of files) {
  const raw = fs.readFileSync(f, "utf8");
  const chunks = chunkText(raw, 1200, 200);
  for (let i = 0; i < chunks.length; i++) {
    documents.push({
      id: `${path.relative(CLONE_DIR, f)}::${i}`,
      text: chunks[i],
      metadata: { path: path.relative(CLONE_DIR, f), repo: GITHUB_REPO },
    });
  }
}
console.log(`Prepared ${documents.length} document chunks`);

/* STEP 3: helper functions to call Nia - embeddings, upsert, search.
   Adjust endpoints to your Nia API. This example assumes:
     POST ${NIA_BASE}/v1/embeddings  body { input: "text" } -> { data: [ { embedding: [..] } ] }
     POST ${NIA_BASE}/v1/indexes/${INDEX_NAME}/upsert body { vectors: [ { id, values, metadata } ] }
     POST ${NIA_BASE}/v1/indexes/${INDEX_NAME}/query body { vector, top_k } -> { matches: [ { id, score, metadata } ] }
*/

async function getEmbedding(text) {
  const res = await fetch(`${NIA_BASE}/v1/embeddings`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${NIA_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ input: text }),
  });
  if (!res.ok) {
    throw new Error(`Embedding error ${res.status}: ${await res.text()}`);
  }
  const j = await res.json();
  // adapt as needed to Nia return shape
  return j.data?.[0]?.embedding ?? j.embedding ?? null;
}

async function upsertVectors(vectors) {
  const res = await fetch(`${NIA_BASE}/v1/indexes/${encodeURIComponent(INDEX_NAME)}/upsert`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${NIA_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ vectors }),
  });
  if (!res.ok) {
    throw new Error(`Upsert error ${res.status}: ${await res.text()}`);
  }
  return res.json();
}

async function searchVector(vector, top_k = 5) {
  const res = await fetch(`${NIA_BASE}/v1/indexes/${encodeURIComponent(INDEX_NAME)}/query`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${NIA_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ vector, top_k }),
  });
  if (!res.ok) {
    throw new Error(`Search error ${res.status}: ${await res.text()}`);
  }
  return res.json();
}

/* Bulk index process (throttled) */
(async () => {
  console.log("Indexing into Nia...");
  const BATCH = 16;
  for (let i = 0; i < documents.length; i += BATCH) {
    const batch = documents.slice(i, i + BATCH);
    const vectors = [];
    // create embeddings sequentially or parallel (but avoid huge parallel)
    for (const doc of batch) {
      const emb = await getEmbedding(doc.text);
      if (!emb) throw new Error("No embedding returned");
      vectors.push({ id: doc.id, values: emb, metadata: doc.metadata });
    }
    await upsertVectors(vectors);
    console.log(`Upserted batch ${i}-${i + batch.length}`);
  }
  console.log("Indexing complete.");

  /* STEP 4: run a tiny MCP adapter for Cursor:
     Expose POST /mcp/query with body { query: string, top_k?: number }
     Cursor will call this endpoint; adapter embeds the query and runs Nia search, then returns hits.
  */
  const app = express();
  app.use(express.json({ limit: "1mb" }));

  app.post("/mcp/query", async (req, res) => {
    try {
      const { query, top_k = 5 } = req.body;
      if (!query) return res.status(400).json({ error: "missing query" });
      const qEmb = await getEmbedding(query);
      const search = await searchVector(qEmb, top_k);
      // adapt response shape as your MCP consumer expects. This is a simple JSON array.
      const hits = (search.matches || search.results || []).map(m => ({
        id: m.id,
        score: m.score ?? m.distance ?? 0,
        metadata: m.metadata ?? {},
      }));
      return res.json({ query, hits });
    } catch (err) {
      console.error(err);
      return res.status(500).json({ error: String(err) });
    }
  });

  // Optional status endpoint Cursor might use to validate the connector.
  app.get("/mcp/info", (req, res) => {
    res.json({ name: "nia-github-mcp", index: INDEX_NAME, repo: GITHUB_REPO });
  });

  app.listen(Number(MCP_PORT), () => {
    console.log(`MCP adapter listening on http://0.0.0.0:${MCP_PORT}`);
    console.log("MCP query endpoint: POST /mcp/query { query, top_k }");
  });
})().catch(err => { console.error(err); process.exit(1); });
```

Summary (quick):
- Provide GitHub token and repo; script clones it.
- Script chunks files and obtains embeddings from Nia.
- Vectors are upserted into a Nia index.
- Script exposes a simple MCP HTTP adapter (/mcp/query) that Cursor can call to get vector-search hits from Nia.

Adjust the Nia endpoint paths and returned JSON shapes to match your Nia deployment and adapt the MCP response shape to Cursor's exact requirements.

```python
# Python example: "NiaOracle" that chooses between two indexes by creating each index,
# running EXPLAIN (ANALYZE, FORMAT JSON) and picking the lower observed execution time.
#
# WARNING: this code creates/drops indexes on the target DB. Run on a test copy or
# ensure you have appropriate permissions. CREATE INDEX CONCURRENTLY requires no transaction.

import json
import time
import psycopg2

class NiaOracle:
    def __init__(self, dsn, runs=3, autocommit=True):
        self.conn = psycopg2.connect(dsn)
        self.conn.autocommit = autocommit
        self.runs = runs

    def _exec(self, sql, params=None):
        with self.conn.cursor() as cur:
            cur.execute(sql, params)
            try:
                return cur.fetchall()
            except psycopg2.ProgrammingError:
                return None

    def _create_index(self, create_sql):
        # expect full CREATE INDEX ... statement (prefer CONCURRENTLY if available)
        self._exec(create_sql)
        # small pause to let index become usable
        time.sleep(0.5)

    def _drop_index(self, index_name, if_exists=True):
        sql = f"DROP INDEX {'IF EXISTS ' if if_exists else ''}{index_name}"
        self._exec(sql)

    def _measure_query(self, query):
        # runs EXPLAIN (ANALYZE, FORMAT JSON) and returns execution time (ms)
        rows = self._exec(f"EXPLAIN (ANALYZE, FORMAT JSON) {query}")
        # rows[0][0] is a JSON string/list; parse it
        plan_json = rows[0][0]
        # plan_json is typically a list with one dict
        if isinstance(plan_json, list):
            doc = plan_json[0]
        else:
            doc = json.loads(plan_json)[0]
        # prefer top-level 'Execution Time' if present, else Plan['Actual Total Time']
        exec_time = doc.get("Execution Time")
        if exec_time is None:
            plan = doc.get("Plan", {})
            exec_time = plan.get("Actual Total Time")
        return float(exec_time)

    def evaluate_index(self, query, index_name, create_sql):
        try:
            self._create_index(create_sql)
            times = []
            for _ in range(self.runs):
                t = self._measure_query(query)
                times.append(t)
            avg = sum(times) / len(times)
            return {"index": index_name, "avg_ms": avg, "raw_ms": times}
        finally:
            # remove index to revert database to original state
            try:
                self._drop_index(index_name)
            except Exception:
                pass

    def choose(self, query, index_options):
        # index_options: list of dicts: {"name": "idx_x", "create_sql": "CREATE INDEX ..."}
        results = []
        for opt in index_options:
            r = self.evaluate_index(query, opt["name"], opt["create_sql"])
            results.append(r)
        # pick lowest avg_ms
        best = min(results, key=lambda x: x["avg_ms"])
        return {"best_index": best["index"], "results": results}

# Example usage:
if __name__ == "__main__":
    DSN = "host=localhost dbname=mydb user=myuser password=mypw"
    oracle = NiaOracle(DSN, runs=2)

    sql_query = "SELECT * FROM orders WHERE customer_id = 123 AND created_at >= '2025-01-01';"

    indexes = [
        {"name": "idx_orders_customer", "create_sql": "CREATE INDEX CONCURRENTLY idx_orders_customer ON orders(customer_id)"},
        {"name": "idx_orders_customer_created", "create_sql": "CREATE INDEX CONCURRENTLY idx_orders_customer_created ON orders(customer_id, created_at)"},
    ]

    decision = oracle.choose(sql_query, indexes)
    print("Chosen index:", decision["best_index"])
    print("All results:", decision["results"])
```
